require 'json';require 'digest';require 'fileutils';require 'open3'
repo,out=ARGV;raise 'fresh checksum test' if File.exist?(out);FileUtils.mkdir_p(out);c="#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include \"#{repo}/patches/m4/typing_probe_sha.inc\"\nint main(void){unsigned char p[1000]; for(int i=0;i<1000;i++)p[i]=(unsigned char)(i%251);int n[]={0,3,55,56,63,64,65,119,120,127,128,1000};for(int j=0;j<12;j++){char h[65];probe_sha256(p,n[j],h);printf(\"%d %s\\n\",n[j],h);}return 0;}\n";File.write(out+'/check.c',c);argv=['/opt/llvm-23.1.1/bin/clang','-O1','-g',out+'/check.c','-o',out+'/check'];o,e,st=Open3.capture3(*argv);File.write(out+'/compile.stdout',o);File.write(out+'/compile.stderr',e);raise 'checksum test build' unless st.success?;o,e,st=Open3.capture3(out+'/check');File.write(out+'/stdout',o);File.write(out+'/stderr',e);raise 'checksum execution' unless st.success?&&e.empty?;rows=o.lines.map{|l|n,h=l.split;n=n.to_i;expected=Digest::SHA256.hexdigest((0...n).map{|i|i%251}.pack('C*'));raise 'checksum boundary '+n.to_s unless h==expected;{bytes:n,sha256:h}};raise '12 lengths' unless rows.size==12;File.write(out+'/summary.json',JSON.pretty_generate({cases:rows,matched:12})+"\n");puts 'PASS SHA256 12 boundaries'
